#!/bin/sh
# Builds kaggle/embed/kernel.py = small Kaggle header + src/embed.py (Kaggle kernels take one file).
cd "$(dirname "$0")/.."
{
cat <<'HDR'
# Kaggle kernel for Stage A (audio embeddings). Generated by kaggle/build_embed.sh from src/embed.py.
import glob, os, sys
_csv = glob.glob("/kaggle/input/**/train.csv", recursive=True)
assert _csv, "competition data not attached"
sys.argv = ["embed.py", "--data", os.path.dirname(_csv[0]), "--out", "/kaggle/working"]
HDR
cat src/embed.py
} > kaggle/embed/kernel.py
echo "built kaggle/embed/kernel.py"
